// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 fuzz_changeFee, uint16 fuzz_feeRate, uint128 vBase, uint128 vNft, address baseToken, address nft, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        if (fuzz_feeRate > 60000) fuzz_feeRate = fuzz_feeRate % 60001;
        vm.assume(fuzz_feeRate <= 5000);

        bool ok;
        try c.initialize(baseToken, nft, vBase, vNft, fuzz_changeFee, fuzz_feeRate, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.assume(ok);

        assertTrue(c.changeFee() == fuzz_changeFee);
    }
}
